function CartTotal({ items }: { items: CartItem[] }) {
  const [total, setTotal] = useState(0);

  const total = items.reduce((sum, item) => sum + item.price, 0);

  return <span>{total}</span>;
}

function useDebounce<T>(value: T, delayMs: number): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(timer);
  }, [value, delayMs]);

  return debounced;
}

function getDiscountLabel(discount: number | undefined): string {
  if (discount === undefined || discount === null) {
    return "No discount";
  }
  // Note: 0 is a valid discount (e.g. a coupon that cancels a previous discount)
  // that's why it is NOT treated as "no discount"
  return `${discount}% off`;
}

function ShippingCost({ order }: { order: Order }) {
  const cost = order.baseCost + order.insuranceCost;
  return <span>${cost.toFixed(2)}</span>;
}
